1	package payflow
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"fmt"
7		"os"
8		"strconv"
9		"unicode/utf8"
10	)
11	
12	// EvalReason is the machine-readable outcome of a flag evaluation.
13	type EvalReason string
14	
15	const (
16		EvalDisabled EvalReason = "disabled"
17		EvalRule     EvalReason = "rule"
18		EvalDefault  EvalReason = "default"
19	)
20	
21	// Condition is one predicate over an evaluation context.
22	type Condition struct {
23		Attribute string
24		Op        string
25		// strVal 用于 eq；inVal 用于 in（至少一项）。
26		strVal string
27		inVal  []string
28	}
29	
30	// Rule groups conditions that must all hold; on match the flag takes Value.
31	type Rule struct {
32		ID         string
33		Value      bool
34		Conditions []Condition
35	}
36	
37	// Flag is one feature toggle with its default and ordered rules.
38	type Flag struct {
39		Key     string
40		Enabled bool
41		Default bool
42		Rules   []Rule
43	}
44	
45	// Config is a validated feature flag configuration.
46	type Config struct {
47		Flags []Flag
48	}
49	
50	// EvalResult is the deterministic outcome of evaluating one flag.
51	type EvalResult struct {
52		Key    string     `json:"key"`
53		Value  bool       `json:"value"`
54		Reason EvalReason `json:"reason"`
55		RuleID *string    `json:"ruleId"`
56	}
57	
58	// Equals reports whether two evaluation results are identical.
59	func (r EvalResult) Equals(other EvalResult) bool {
60		if r.Key != other.Key || r.Value != other.Value || r.Reason != other.Reason {
61			return false
62		}
63		if (r.RuleID == nil) != (other.RuleID == nil) {
64			return false
65		}
66		if r.RuleID != nil && *r.RuleID != *other.RuleID {
67			return false
68		}
69		return true
70	}
71	
72	// Context is a validated map of attribute names to string values.
73	type Context struct {
74		values map[string]string
75	}
76	
77	// LoadConfig reads and strictly validates a UTF-8 JSON flag config file.
78	// 所有开关都会被完整校验，包括不会被求值或已关闭的开关。
79	func LoadConfig(path string) (*Config, error) {
80		raw, err := os.ReadFile(path)
81		if err != nil {
82			return nil, fmt.Errorf("cannot read config file %q: %w", path, err)
83		}
84		return ParseConfig(raw)
85	}
86	
87	// LoadContext reads and validates a UTF-8 JSON context file.
88	func LoadContext(path string) (*Context, error) {
89		raw, err := os.ReadFile(path)
90		if err != nil {
91			return nil, fmt.Errorf("cannot read context file %q: %w", path, err)
92		}
93		return ParseContext(raw)
94	}
95	
96	// ParseConfig parses a config document from JSON bytes with strict typing.
97	// 先解析到 any 再逐字段校验，以区分“字段缺失”与“显式提供的 false”。
98	func ParseConfig(raw []byte) (*Config, error) {
99		if !utf8.Valid(raw) {
100			return nil, fmt.Errorf("config: file is not valid UTF-8")
101		}
102		if err := rejectInvalidUnicodeEscapes(raw, "config"); err != nil {
103			return nil, err
104		}
105		if err := rejectDuplicateFields(raw, "config"); err != nil {
106			return nil, err
107		}
108		var doc any
109		if err := json.Unmarshal(raw, &doc); err != nil {
110			return nil, fmt.Errorf("config: invalid JSON: %w", err)
111		}
112		root, ok := doc.(map[string]any)
113		if !ok {
114			return nil, fmt.Errorf("config: top level must be a JSON object")
115		}
116		flagsRaw, present := root["flags"]
117		if !present {
118			return nil, fmt.Errorf("config.flags: field is required")
119		}
120		if flagsRaw == nil {
121			return nil, fmt.Errorf("config.flags: must be an array, got null")
122		}
123		flagsArr, ok := flagsRaw.([]any)
124		if !ok {
125			return nil, fmt.Errorf("config.flags: must be an array")
126		}
127		cfg := &Config{}
128		seenKeys := map[string]int{}
129		for i, fr := range flagsArr {
130			flag, err := parseFlag(fr, i)
131			if err != nil {
132				return nil, err
133			}
134			if prev, dup := seenKeys[flag.Key]; dup {
135				return nil, fmt.Errorf("config.flags[%d].key: duplicate flag key %q (first at flags[%d])", i, flag.Key, prev)
136			}
137			seenKeys[flag.Key] = i
138			cfg.Flags = append(cfg.Flags, flag)
139		}
140		return cfg, nil
141	}
142	
143	// ParseContext parses an attribute-name -> string context object; it may be empty.
144	func ParseContext(raw []byte) (*Context, error) {
145		if !utf8.Valid(raw) {
146			return nil, fmt.Errorf("context: file is not valid UTF-8")
147		}
148		if err := rejectInvalidUnicodeEscapes(raw, "context"); err != nil {
149			return nil, err
150		}
151		if err := rejectDuplicateFields(raw, "context"); err != nil {
152			return nil, err
153		}
154		var doc any
155		if err := json.Unmarshal(raw, &doc); err != nil {
156			return nil, fmt.Errorf("context: invalid JSON: %w", err)
157		}
158		root, ok := doc.(map[string]any)
159		if !ok {
160			return nil, fmt.Errorf("context: top level must be a JSON object")
161		}
162		ctx := &Context{values: make(map[string]string, len(root))}
163		for k, v := range root {
164			s, ok := v.(string)
165			if !ok {
166				return nil, fmt.Errorf("context.%s: value must be a string", k)
167			}
168			ctx.values[k] = s
169		}
170		return ctx, nil
171	}
172	
173	// Get looks up an attribute; an empty string is a legal value.
174	func (c *Context) Get(attribute string) (string, bool) {
175		if c == nil {
176			return "", false
177		}
178		v, ok := c.values[attribute]
179		return v, ok
180	}
181	
182	// Find returns the flag with the given key, or nil if absent.
183	func (c *Config) Find(key string) *Flag {
184		if c == nil {
185			return nil
186		}
187		for i := range c.Flags {
188			if c.Flags[i].Key == key {
189				return &c.Flags[i]
190			}
191		}
192		return nil
193	}
194	
195	// Evaluate deterministically evaluates a flag against a context.
196	// 未启用固定 false（reason=disabled），不使用默认值或规则；启用后取首条
197	// 所有条件均成立的规则的 value；无匹配取 default。求值不依赖时间、随机数
198	// 或 map 遍历顺序，同一配置与上下文重复求值结果一致。
199	func (f *Flag) Evaluate(ctx *Context) EvalResult {
200		if !f.Enabled {
201			return EvalResult{Key: f.Key, Value: false, Reason: EvalDisabled, RuleID: nil}
202		}
203		for i := range f.Rules {
204			rule := &f.Rules[i]
205			if rule.matches(ctx) {
206				id := rule.ID
207				return EvalResult{Key: f.Key, Value: rule.Value, Reason: EvalRule, RuleID: &id}
208			}
209		}
210		return EvalResult{Key: f.Key, Value: f.Default, Reason: EvalDefault, RuleID: nil}
211	}
212	
213	func (r *Rule) matches(ctx *Context) bool {
214		for i := range r.Conditions {
215			if !r.Conditions[i].matches(ctx) {
216				return false
217			}
218		}
219		return true
220	}
221	
222	func (c Condition) matches(ctx *Context) bool {
223		v, present := ctx.Get(c.Attribute)
224		if !present {
225			return false
226		}
227		switch c.Op {
228		case "eq":
229			return v == c.strVal
230		case "in":
231			for _, candidate := range c.inVal {
232				if v == candidate {
233					return true
234				}
235			}
236			return false
237		default:
238			// 解析阶段已拒绝未知运算符，防御性处理。
239			return false
240		}
241	}
242	
243	// MarshalResult renders the result as a single compact JSON object.
244	func MarshalResult(r EvalResult) ([]byte, error) {
245		var buf bytes.Buffer
246		enc := json.NewEncoder(&buf)
247		enc.SetEscapeHTML(false)
248		if err := enc.Encode(r); err != nil {
249			return nil, err
250		}
251		return bytes.TrimRight(buf.Bytes(), "\n"), nil
252	}
253	
254	// --- strict parsing helpers -------------------------------------------------
255	
256	// jsonFrame 是 JSON 原文遍历中一个对象或数组的层级状态。重复字段检查与非法
257	// Unicode 转义检查共用这一份层级与位置定义，调整错误定位时只需改这一处。
258	type jsonFrame struct {
259		path   string // 容器自身的完整位置，如 config.flags[0].rules[1]
260		object bool
261		// keys 记录本对象已声明的字段名（按解码后的字符串），仅重复字段检查使用；
262		// Unicode 遍历不登记字段，保持 nil。
263		keys map[string]struct{}
264		// lastKey 是对象最近一个字段名，用于拼出字段值的位置。
265		lastKey string
266		// expectKey 标记对象内下一个字符串是否为字段名。
267		expectKey bool
268		// nextIndex 是数组下一个元素的下标。
269		nextIndex int
270	}
271	
272	// jsonPathTracker 是两类 JSON 检查共用的对象层级、数组位置与字段路径状态机。
273	// label 是根容器的位置前缀（"config" 或 "context"）。
274	type jsonPathTracker struct {
275		label string
276		stack []*jsonFrame
277	}
278	
279	func newJSONPathTracker(label string) *jsonPathTracker {
280		return &jsonPathTracker{label: label}
281	}
282	
283	func (t *jsonPathTracker) top() *jsonFrame {
284		return t.stack[len(t.stack)-1]
285	}
286	
287	// childPath 拼出栈顶容器内下一个子值的位置：对象的字段值用 .字段名，
288	// 数组元素用 [下标]。
289	func (t *jsonPathTracker) childPath() string {
290		top := t.top()
291		if top.object {
292			return top.path + "." + top.lastKey
293		}
294		return top.path + "[" + strconv.Itoa(top.nextIndex) + "]"
295	}
296	
297	// beginContainer 在遇到 '{' 或 '[' 时压入新容器，返回新容器的完整位置。
298	func (t *jsonPathTracker) beginContainer(object bool) string {
299		path := t.label
300		if len(t.stack) > 0 {
301			path = t.childPath()
302		}
303		t.stack = append(t.stack, &jsonFrame{path: path, object: object, expectKey: object})
304		return path
305	}
306	
307	// endContainer 在遇到 '}' 或 ']' 时弹出容器，并把整个容器计为父容器中
308	// 一个已完成的值。
309	func (t *jsonPathTracker) endContainer() {
310		if len(t.stack) > 0 {
311			t.stack = t.stack[:len(t.stack)-1]
312		}
313		t.endValue()
314	}
315	
316	// atKey 报告下一个字符串是否应按对象字段名处理。
317	func (t *jsonPathTracker) atKey() bool {
318		return len(t.stack) > 0 && t.top().object && t.top().expectKey
319	}
320	
321	// currentPath 返回当前容器自身的位置（字段名报错时指向所属对象）；
322	// 栈为空时返回根标签。
323	func (t *jsonPathTracker) currentPath() string {
324		if len(t.stack) == 0 {
325			return t.label
326		}
327		return t.top().path
328	}
329	
330	// valuePath 拼出下一个字符串值（字段值或数组元素）的位置，但不改变状态。
331	func (t *jsonPathTracker) valuePath() string {
332		if len(t.stack) == 0 {
333			return t.label
334		}
335		return t.childPath()
336	}
337	
338	// endValue 在一个字段值或数组元素完成后调用：对象回到等待字段名的状态，
339	// 数组推进元素下标。
340	func (t *jsonPathTracker) endValue() {
341		if len(t.stack) == 0 {
342			return
343		}
344		top := t.top()
345		if top.object {
346			top.expectKey = true
347		} else {
348			top.nextIndex++
349		}
350	}
351	
352	// noteKey 登记一个已解码的对象字段名：更新字段路径状态，并在同一对象内第二次
353	// 声明同名字段时返回重复字段错误。
354	func (t *jsonPathTracker) noteKey(name string) error {
355		top := t.top()
356		if top.keys == nil {
357			top.keys = make(map[string]struct{})
358		}
359		if _, dup := top.keys[name]; dup {
360			return fmt.Errorf("%s.%s: duplicate field %q", top.path, name, name)
361		}
362		top.keys[name] = struct{}{}
363		top.lastKey = name
364		top.expectKey = false
365		return nil
366	}
367	
368	// setKey 在不做重复检查的遍历（Unicode 扫描）中记录一个成功解码的字段名，
369	// 仅维护字段值路径所需的状态。
370	func (t *jsonPathTracker) setKey(name string) {
371		top := t.top()
372		top.lastKey = name
373		top.expectKey = false
374	}
375	
376	// noteInvalidKey 在字段名无法解码（属于 JSON 语法错误）时仅推进键值状态：
377	// 不覆盖已记录的字段名；语法错误留给后续 Unmarshal 报告。
378	func (t *jsonPathTracker) noteInvalidKey() {
379		t.top().expectKey = false
380	}
381	
382	// rejectDuplicateFields 按文件原文顺序扫描 JSON 令牌流，拒绝任何在同一对象内
383	// 重复声明的字段名。字段名按解码后的字符串比较（"enabled" 与 "énabled"
384	// 同名），大小写不同仍是不同字段，名字中的空白不裁剪。检查覆盖所有对象，
385	// 包括附加字段里嵌套的对象；数组元素不属于这一检查。label 是根对象的位置
386	// 前缀（"config" 或 "context"）。对象层级、数组下标与字段路径由
387	// jsonPathTracker 统一维护。JSON 语法错误不在此报告（令牌流失效即停止），
388	// 留给 Unmarshal。
389	func rejectDuplicateFields(raw []byte, label string) error {
390		dec := json.NewDecoder(bytes.NewReader(raw))
391		tracker := newJSONPathTracker(label)
392		for {
393			tok, err := dec.Token()
394			if err != nil {
395				// io.EOF 或语法错误；语法错误由后续 Unmarshal 报告。
396				break
397			}
398			switch t := tok.(type) {
399			case json.Delim:
400				switch t {
401				case '{':
402					tracker.beginContainer(true)
403				case '[':
404					tracker.beginContainer(false)
405				case '}', ']':
406					tracker.endContainer()
407				}
408			case string:
409				if tracker.atKey() {
410					if err := tracker.noteKey(t); err != nil {
411						return err
412					}
413				} else {
414					tracker.endValue()
415				}
416			default:
417				tracker.endValue()
418			}
419		}
420		return nil
421	}
422	
423	// rejectInvalidUnicodeEscapes 按文件原文顺序扫描 JSON 文本，拒绝任何不能组成
424	// 完整字符的 \uXXXX 转义：孤立的高代理项、孤立的低代理项，以及不完整或顺序
425	// 错误的代理项对。encoding/json 解码时会把这类转义静默替换为 U+FFFD，使非法
426	// 输入与真正的 "�" 被当作相同字符串参与求值，或让字段名在替换后被误判为重复，
427	// 因此必须在解码前按原文拒绝。检查覆盖字段名与所有字符串值（包括规则的比较值、
428	// in 列表元素以及附加字段里的字符串），一个文件有多个问题时报告原文中最先出现
429	// 的一处。label 是根对象的位置前缀（"config" 或 "context"）。对象层级、数组
430	// 下标与字段路径由 jsonPathTracker 统一维护；JSON 语法错误不在此报告，留给
431	// Unmarshal。
432	func rejectInvalidUnicodeEscapes(raw []byte, label string) error {
433		tracker := newJSONPathTracker(label)
434		i := 0
435		for i < len(raw) {
436			c := raw[i]
437			switch {
438			case c == '{' || c == '[':
439				tracker.beginContainer(c == '{')
440				i++
441			case c == '}' || c == ']':
442				tracker.endContainer()
443				i++
444			case c == '"':
445				end := jsonStringEnd(raw, i)
446				contentEnd := end
447				if contentEnd > i+1 && raw[contentEnd-1] == '"' {
448					contentEnd-- // 去掉右引号；未终止的字符串留给 Unmarshal 报告
449				}
450				content := raw[i+1 : contentEnd]
451				if tracker.atKey() {
452					if bad := findBadUnicodeEscape(content); bad != nil {
453						return fmt.Errorf("%s: field name %q contains invalid Unicode escape %s: Unicode escape does not form a complete character (%s)",
454							tracker.currentPath(), string(content), bad.escape, bad.detail)
455					}
456					// 转义已校验合法，解码用于定位路径；失败说明是语法错误，留给 Unmarshal。
457					if name, ok := decodeJSONString(raw[i:end]); ok {
458						tracker.setKey(name)
459					} else {
460						tracker.noteInvalidKey()
461					}
462				} else {
463					path := tracker.valuePath()
464					if bad := findBadUnicodeEscape(content); bad != nil {
465						return fmt.Errorf("%s: invalid Unicode escape %s: Unicode escape does not form a complete character (%s)",
466							path, bad.escape, bad.detail)
467					}
468					tracker.endValue()
469				}
470				i = end
471			case c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == ':' || c == ',':
472				i++
473			default:
474				// 数字与 true/false/null 等标量：跳过至下一个结构字符，按一个值计。
475				for i < len(raw) && !isJSONStructural(raw[i]) {
476					i++
477				}
478				tracker.endValue()
479			}
480		}
481		return nil
482	}
483	
484	// decodeJSONString 解码一个完整的 JSON 字符串字面量（含两侧引号）；ok 为 false
485	// 表示字面量本身非法（未终止或转义写法错误等），属于 JSON 语法错误。
486	func decodeJSONString(lit []byte) (s string, ok bool) {
487		if err := json.Unmarshal(lit, &s); err != nil {
488			return "", false
489		}
490		return s, true
491	}
492	
493	// badEscape 描述一处不能组成完整字符的 \uXXXX 转义。
494	type badEscape struct {
495		escape string // 原文中的转义序列，如 \uD800
496		detail string // 具体问题（孤立高代理项/孤立低代理项）
497	}
498	
499	// jsonStringEnd 返回从 raw[i]（必须是 '"'）开始的字符串字面量结束位置
500	// （右引号之后的下标）；未终止时返回 len(raw)。
501	func jsonStringEnd(raw []byte, i int) int {
502		j := i + 1
503		for j < len(raw) {
504			switch raw[j] {
505			case '\\':
506				j += 2
507			case '"':
508				return j + 1
509			default:
510				j++
511			}
512		}
513		return len(raw)
514	}
515	
516	// findBadUnicodeEscape 在字符串内容（不含引号）中查找第一处不能组成完整
517	// 字符的 \uXXXX 转义；没有则返回 nil。反斜杠本身的转义（\\）先于 \u 判定，
518	// 因此 "\\uD800" 只是普通文本。非法的 \u 写法（非 4 位十六进制）属于 JSON
519	// 语法错误，不在此报告。
520	func findBadUnicodeEscape(content []byte) *badEscape {
521		j := 0
522		for j < len(content) {
523			if content[j] != '\\' {
524				j++
525				continue
526			}
527			if j+1 >= len(content) {
528				break
529			}
530			if content[j+1] != 'u' {
531				j += 2
532				continue
533			}
534			if j+6 > len(content) || !isHex4(content[j+2:j+6]) {
535				j += 2
536				continue
537			}
538			cp := hexVal4(content[j+2 : j+6])
539			switch {
540			case cp >= 0xD800 && cp <= 0xDBFF:
541				// 高代理项只有紧跟一个低代理项转义才组成完整字符。
542				if j+12 <= len(content) && content[j+6] == '\\' && content[j+7] == 'u' &&
543					isHex4(content[j+8:j+12]) {
544					if lo := hexVal4(content[j+8 : j+12]); lo >= 0xDC00 && lo <= 0xDFFF {
545						j += 12
546						continue
547					}
548				}
549				return &badEscape{
550					escape: string(content[j : j+6]),
551					detail: "high surrogate is not followed by a low surrogate",
552				}
553			case cp >= 0xDC00 && cp <= 0xDFFF:
554				return &badEscape{
555					escape: string(content[j : j+6]),
556					detail: "low surrogate is not preceded by a high surrogate",
557				}
558			}
559			j += 6
560		}
561		return nil
562	}
563	
564	// isJSONStructural 报告 b 是否为 JSON 结构字符或空白（标量值的边界）。
565	func isJSONStructural(b byte) bool {
566		switch b {
567		case ' ', '\t', '\n', '\r', '{', '}', '[', ']', ':', ',', '"':
568			return true
569		}
570		return false
571	}
572	
573	// isHex4 报告 b 是否恰好为 4 个十六进制数字。
574	func isHex4(b []byte) bool {
575		if len(b) != 4 {
576			return false
577		}
578		for _, c := range b {
579			if !isHexDigit(c) {
580				return false
581			}
582		}
583		return true
584	}
585	
586	func isHexDigit(c byte) bool {
587		return ('0' <= c && c <= '9') || ('a' <= c && c <= 'f') || ('A' <= c && c <= 'F')
588	}
589	
590	// hexVal4 把 4 个十六进制数字解析为码点值；调用前须先经 isHex4 校验。
591	func hexVal4(b []byte) int {
592		v := 0
593		for _, c := range b {
594			v <<= 4
595			switch {
596			case '0' <= c && c <= '9':
597				v |= int(c - '0')
598			case 'a' <= c && c <= 'f':
599				v |= int(c-'a') + 10
600			default: // 'A' <= c && c <= 'F'
601				v |= int(c-'A') + 10
602			}
603		}
604		return v
605	}
606	
607	func parseFlag(raw any, index int) (Flag, error) {
608		loc := fmt.Sprintf("config.flags[%d]", index)
609		obj, ok := raw.(map[string]any)
610		if !ok {
611			return Flag{}, fmt.Errorf("%s: flag must be a JSON object", loc)
612		}
613		key, err := requireNonEmptyString(obj, "key", loc)
614		if err != nil {
615			return Flag{}, err
616		}
617		enabled, err := requireBool(obj, "enabled", loc)
618		if err != nil {
619			return Flag{}, err
620		}
621		def, err := requireBool(obj, "default", loc)
622		if err != nil {
623			return Flag{}, err
624		}
625		rulesArr, err := requireArrayField(obj, "rules", loc)
626		if err != nil {
627			return Flag{}, err
628		}
629		flag := Flag{Key: key, Enabled: enabled, Default: def}
630		seenRules := map[string]int{}
631		for ri, rv := range rulesArr {
632			rule, err := parseRule(rv, index, ri)
633			if err != nil {
634				return Flag{}, err
635			}
636			if prev, dup := seenRules[rule.ID]; dup {
637				return Flag{}, fmt.Errorf("%s.rules[%d].id: duplicate rule id %q (first at rules[%d])", loc, ri, rule.ID, prev)
638			}
639			seenRules[rule.ID] = ri
640			flag.Rules = append(flag.Rules, rule)
641		}
642		return flag, nil
643	}
644	
645	func parseRule(raw any, flagIndex, ruleIndex int) (Rule, error) {
646		loc := fmt.Sprintf("config.flags[%d].rules[%d]", flagIndex, ruleIndex)
647		obj, ok := raw.(map[string]any)
648		if !ok {
649			return Rule{}, fmt.Errorf("%s: rule must be a JSON object", loc)
650		}
651		id, err := requireNonEmptyString(obj, "id", loc)
652		if err != nil {
653			return Rule{}, err
654		}
655		value, err := requireBool(obj, "value", loc)
656		if err != nil {
657			return Rule{}, err
658		}
659		condsArr, err := requireArrayField(obj, "conditions", loc)
660		if err != nil {
661			return Rule{}, err
662		}
663		if len(condsArr) == 0 {
664			return Rule{}, fmt.Errorf("%s.conditions: must contain at least one condition", loc)
665		}
666		rule := Rule{ID: id, Value: value}
667		for ci, cv := range condsArr {
668			cond, err := parseCondition(cv, flagIndex, ruleIndex, ci)
669			if err != nil {
670				return Rule{}, err
671			}
672			rule.Conditions = append(rule.Conditions, cond)
673		}
674		return rule, nil
675	}
676	
677	func parseCondition(raw any, flagIndex, ruleIndex, condIndex int) (Condition, error) {
678		loc := fmt.Sprintf("config.flags[%d].rules[%d].conditions[%d]", flagIndex, ruleIndex, condIndex)
679		obj, ok := raw.(map[string]any)
680		if !ok {
681			return Condition{}, fmt.Errorf("%s: condition must be a JSON object", loc)
682		}
683		attribute, err := requireNonEmptyString(obj, "attribute", loc)
684		if err != nil {
685			return Condition{}, err
686		}
687		op, err := requireNonEmptyString(obj, "op", loc)
688		if err != nil {
689			return Condition{}, err
690		}
691		valueField, err := requireField(obj, "value", loc)
692		if err != nil {
693			return Condition{}, err
694		}
695		cond := Condition{Attribute: attribute, Op: op}
696		switch op {
697		case "eq":
698			s, ok := valueField.(string)
699			if !ok {
700				return Condition{}, fmt.Errorf("%s.value: must be a string when op is %q", loc, op)
701			}
702			cond.strVal = s
703		case "in":
704			arr, ok := valueField.([]any)
705			if !ok {
706				return Condition{}, fmt.Errorf("%s.value: must be an array when op is %q", loc, op)
707			}
708			if len(arr) == 0 {
709				return Condition{}, fmt.Errorf("%s.value: in-list must contain at least one item", loc)
710			}
711			for ii, item := range arr {
712				s, ok := item.(string)
713				if !ok {
714					return Condition{}, fmt.Errorf("%s.value[%d]: must be a string", loc, ii)
715				}
716				cond.inVal = append(cond.inVal, s)
717			}
718		default:
719			return Condition{}, fmt.Errorf("%s.op: unknown operator %q (allowed: eq, in)", loc, op)
720		}
721		return cond, nil
722	}
723	
724	func requireField(obj map[string]any, name, loc string) (any, error) {
725		v, ok := obj[name]
726		if !ok {
727			return nil, fmt.Errorf("%s.%s: field is required", loc, name)
728		}
729		if v == nil {
730			return nil, fmt.Errorf("%s.%s: must not be null", loc, name)
731		}
732		return v, nil
733	}
734	
735	func requireArrayField(obj map[string]any, name, loc string) ([]any, error) {
736		v, err := requireField(obj, name, loc)
737		if err != nil {
738			return nil, err
739		}
740		arr, ok := v.([]any)
741		if !ok {
742			return nil, fmt.Errorf("%s.%s: must be an array", loc, name)
743		}
744		return arr, nil
745	}
746	
747	func requireNonEmptyString(obj map[string]any, name, loc string) (string, error) {
748		v, err := requireField(obj, name, loc)
749		if err != nil {
750			return "", err
751		}
752		s, ok := v.(string)
753		if !ok {
754			return "", fmt.Errorf("%s.%s: must be a string", loc, name)
755		}
756		if s == "" {
757			return "", fmt.Errorf("%s.%s: must not be empty", loc, name)
758		}
759		return s, nil
760	}
761	
762	func requireBool(obj map[string]any, name, loc string) (bool, error) {
763		v, err := requireField(obj, name, loc)
764		if err != nil {
765			return false, err
766		}
767		b, ok := v.(bool)
768		if !ok {
769			return false, fmt.Errorf("%s.%s: must be a boolean", loc, name)
770		}
771		return b, nil
772	}
