488				`conditions[0].value`}, {"high at end of string", `{"flags":[{"key":"f","enabled":true,"default":false,"rules":[
489				{"id":"r","value":true,"conditions":[{"attribute":"a","op":"eq","value":"x\uD800"}]}]}]}`,
490				`conditions[0].value`},
491			{"in-list element", `{"flags":[{"key":"f","enabled":true,"default":false,"rules":[
492				{"id":"r","value":true,"conditions":[{"attribute":"a","op":"in","value":["ok","\uD800"]}]}]}]}`,
493				`config.flags[0].rules[0].conditions[0].value[1]`},
494			{"flag key string", `{"flags":[{"key":"\uD800","enabled":true,"default":false,"rules":[]}]}`,
495				`config.flags[0].key`},
496			{"extra field value", `{"flags":[{"key":"f","enabled":true,"default":false,"rules":[],
497				"meta":{"note":"\uDFFF"}}]}`,
498				`config.flags[0].meta.note`},
499			{"disabled flag not exempt", `{"flags":[{"key":"f","enabled":false,"default":false,"rules":[
500				{"id":"r","value":true,"conditions":[{"attribute":"a","op":"eq","value":"\uD800"}]}]}]}`,
501				`conditions[0].value`},
502			{"unselected flag not exempt", `{"flags":[
503				{"key":"good","enabled":true,"default":false,"rules":[]},
504				{"key":"bad","enabled":true,"default":false,"rules":[
505					{"id":"r","value":true,"conditions":[{"attribute":"a","op":"eq","value":"\uD800"}]}]}]}`,
506				`config.flags[1].rules[0].conditions[0].value`},
507			{"first error in file order wins", `{"flags":[
508				{"key":"f","enabled":true,"default":false,"rules":[
509					{"id":"r","value":true,"conditions":[{"attribute":"a","op":"eq","value":"\uD800"}]}]},
510				{"key":"g","enabled":true,"default":false,"rules":[
511					{"id":"r","value":true,"conditions":[{"attribute":"a","op":"eq","value":"\uDC00"}]}]}]}`,
512				`config.flags[0].rules[0].conditions[0].value`},
513		}
514		for _, tc := range configCases {
515			t.Run(tc.name, func(t *testing.T) {
516				_, err := ParseConfig([]byte(tc.raw))
517				if err == nil {
518					t.Fatalf("expected invalid Unicode escape error, got nil\nconfig: %s", tc.raw)
519				}
520				if !strings.Contains(err.Error(), incomplete) {
521					t.Fatalf("error = %q, want wording %q", err.Error(), incomplete)
522				}
523				if !strings.Contains(err.Error(), tc.want) {
524					t.Fatalf("error = %q, want location %q", err.Error(), tc.want)
525				}
526			})
527		}
528	
529		// 字段名本身非法：指出所属对象，并保留可辨认的原始转义内容。
530		_, err := ParseConfig([]byte(`{"flags":[{"key":"f","enabled":true,"default":false,"rules":[],
531			"met\uD800a":1}]}`))
532		if err == nil || !strings.Contains(err.Error(), `config.flags[0]`) ||
533			!strings.Contains(err.Error(), `\uD800`) || !strings.Contains(err.Error(), incomplete) {
534			t.Fatalf("bad field name in config: err=%v", err)
535		}
536	
537		// 上下文同样检查值与字段名。
538		_, err = ParseContext([]byte(`{"plan":"\uD800"}`))
539		if err == nil || !strings.Contains(err.Error(), `context.plan`) ||
540			!strings.Contains(err.Error(), incomplete) {
541			t.Fatalf("context value: err=%v", err)
542		}
543		_, err = ParseContext([]byte(`{"pl\uDC00an":"pro"}`))
544		if err == nil || !strings.Contains(err.Error(), `context`) ||
545			!strings.Contains(err.Error(), `\uDC00`) || !strings.Contains(err.Error(), incomplete) {
546			t.Fatalf("context field name: err=%v", err)
547		}
548	}
549	
550	func TestInvalidUnicodeEscapeNotEquatedWithReplacementChar(t *testing.T) {
551		// 规则要求属性值等于真正的 "�"：上下文提供 "\uD800" 不能在替换后命中规则，
552		// 整个求值必须失败。
553		cfg := `{"flags":[{"key":"f","enabled":true,"default":false,"rules":[
554			{"id":"r1","value":true,"conditions":[{"attribute":"plan","op":"eq","value":"�"}]}]}]}`
555		if _, err := ParseContext([]byte(`{"plan":"\uD800"}`)); err == nil {
556			t.Fatal("context with lone surrogate must be rejected, not replaced by U+FFFD")
557		}
558		c := mustParseConfig(t, cfg)
559		ctx := mustParseContext(t, `{"plan":"�"}`)
560		if got := c.Find("f").Evaluate(ctx); got.Reason != EvalRule {
561			t.Fatalf("literal U+FFFD still matches: %+v", got)
562		}
563		// 字段名被替换后也不能误报重复字段："\uD800x" 与 "�x" 本不应同名，
564		// 但非法转义必须先于重复字段检查以自身名义报错。
565		_, err := ParseContext([]byte(`{"\uD800x":"a","�x":"b"}`))
566		if err == nil || strings.Contains(err.Error(), "duplicate field") {
567			t.Fatalf("lone surrogate in field name must not surface as duplicate field: %v", err)
568		}
569	}
570	
571	func TestValidUnicodeEscapesUnchanged(t *testing.T) {
572		// 正确配对的代理项转义与直接写出的同一字符按同一字符串比较。
573		// emojiEsc 是 "😀" 的代理项对转义形式（分两段书写仅为避免源码层面的转义歧义）。
574		emojiEsc := `\uD83D` + `\uDE00`
575		cfgEsc := `{"flags":[{"key":"f","enabled":true,"default":false,"rules":[
576			{"id":"r1","value":true,"conditions":[{"attribute":"emoji","op":"eq","value":"` + emojiEsc + `"}]}]}]}`
577		if got := eval(t, cfgEsc, "f", `{"emoji":"😀"}`); got.Reason != EvalRule {
578			t.Fatalf("paired escape equals literal: %+v", got)
579		}
580		cfgLit := `{"flags":[{"key":"f","enabled":true,"default":false,"rules":[
581			{"id":"r1","value":true,"conditions":[{"attribute":"emoji","op":"eq","value":"😀"}]}]}]}`
582		if got := eval(t, cfgLit, "f", `{"emoji":"`+emojiEsc+`"}`); got.Reason != EvalRule {
583			t.Fatalf("literal equals paired escape: %+v", got)
584		}
585		// 真正的 "�" 与 "�" 仍是合法字符串，不能一概禁止替换字符。
586		mustParseContext(t, `{"a":"�","b":"\u`+`FFFD"}`)
587		if got := eval(t, cfgLit, "f", `{"emoji":"�"}`); got.Reason != EvalDefault {
588			t.Fatalf("U+FFFD is just another string: %+v", got)
589		}
590		// 反斜杠转义后的 "\uD800" 是普通文本（内容为 \uD800 六个字符）。
591		mustParseContext(t, `{"a":"\\uD800"}`)
592		cfgText := `{"flags":[{"key":"f","enabled":true,"default":false,"rules":[
593			{"id":"r1","value":true,"conditions":[{"attribute":"a","op":"eq","value":"\\uD800"}]}]}]}`
594		if got := eval(t, cfgText, "f", `{"a":"\\uD800"}`); got.Reason != EvalRule {
595			t.Fatalf("escaped backslash text: %+v", got)
596		}
597	}
598	
599	func TestEmptyFlagListAndFind(t *testing.T) {
600		cfg := mustParseConfig(t, `{"flags":[]}`)
601		if cfg.Find("missing") != nil {
602			t.Error("expected nil flag")
603		}
604		var nilCfg *Config
605		if nilCfg.Find("x") != nil {
606			t.Error("nil config Find should be nil")
607		}
608		flag := (&Flag{Key: "f", Enabled: false})
609		if got := flag.Evaluate(nil); got.Reason != EvalDisabled {
610			t.Errorf("nil context on disabled flag: %+v", got)
611		}
612	}
